  const textClean = text.trimEnd();
  if (textClean.length === 0) {
    return [];
  }

  const lines = textClean.split('\n');
  const messages: string[] = [];
  let currentMessage = '';
  let currentLength = 0;

  for (const line of lines) {
    if (currentMessage.length === 0 && line.length > 0) {
      if (line.length <= limit) {
        currentMessage = line;
        currentLength = line.length;
        continue;
      }
    }

    const separator = currentMessage.length > 0 ? '\n' : '';
