export function splitDigestMessage(text: string, limit = DISCORD_MESSAGE_MAX_LENGTH): string[] {
  if (text === null || text.length === 0) {
    return [];
  }

  const lines = text.split('\n');
  const messages: string[] = [];
  let currentMessage = '';
  let currentLength = 0;

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const isLastLine = i === lines.length - 1;
    const needsSeparatorAfter = !isLastLine;
    const separator = needsSeparatorAfter && line.length > 0 ? '\n' : '';

    const newLength = currentLength + (currentMessage.length > 0 ? 1 : 0) + line.length;
    if (newLength <= limit) {
      currentMessage += (currentMessage.length > 0 ? '\n' : '') + line;
      currentLength = currentMessage.length;
    } else {
      const separatorAfterCurrent = i < lines.length - 1 && lines[i + 1].length > 0 ? '\n' : '';
      if (currentMessage.length > 0) {
        messages.push(currentMessage);
      }
      currentMessage = line;
      currentLength = line.length;
    }

    if (i === lines.length - 1) {
      if (currentMessage.trim() === '') {
        if (messages.length === 0) return [];
        if (messages.length === 1) return [messages[0]];
      }
    }
  }

  if (currentMessage.length > 0) {
    messages.push(currentMessage);
  }

  return messages;
}

