export function splitDigestMessage(text: string, limit = DISCORD_MESSAGE_MAX_LENGTH): string[] {
  if (!text || text.length === 0) {
    return [];
  }

  const lines = text.split('\n');
  const blocks: string[][] = [];
  let currentBlock: string[] = [];

  // Group lines into blocks separated by blank lines
  for (const line of lines) {
    if (line.length === 0) {
      if (currentBlock.length > 0) {
        blocks.push(currentBlock);
        currentBlock = [];
      }
    } else {
      currentBlock.push(line);
    }
  }
  if (currentBlock.length > 0) {
    blocks.push(currentBlock);
  }

  const messages: string[] = [];
  for (const block of blocks) {
    const blockText = block.join('\n');
    if (blockText.length <= limit) {
      messages.push(blockText);
    } else {
      for (let i = 0; i < blockText.length; i += limit) {
        messages.push(blockText.substring(i, i + limit));
      }
    }
  }

  return messages;
}

